#!/usr/bin/env node
// Generates src/protocol/types.ts and src/protocol/schema.ts from the device-protocol JSON Schema
// published by getproperty-api (`contract/device-protocol.json`). The source sha256 is pinned in
// protocol.lock.json; `--check` fails when the source moved or the generated files are stale.
import { createHash } from 'node:crypto';
import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, relative, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const check = process.argv.includes('--check');
const sourcePath = resolve(root, process.env.PROTOCOL_SOURCE ?? '../getproperty-api/contract/device-protocol.json');
const lockPath = resolve(root, 'protocol.lock.json');
const typesPath = resolve(root, 'src/protocol/types.ts');
const schemaPath = resolve(root, 'src/protocol/schema.ts');

const lock = existsSync(lockPath) ? JSON.parse(readFileSync(lockPath, 'utf8')) : null;

function fail(msg) {
  console.error(`gen:protocol: ${msg}`);
  process.exit(1);
}

let raw;
if (existsSync(sourcePath)) {
  raw = readFileSync(sourcePath, 'utf8');
} else if (check && existsSync(schemaPath)) {
  // No sibling checkout (e.g. CI of this repo alone): verify the vendored copy against the lock.
  const m = /export const PROTOCOL_SHA256 = '([0-9a-f]{64})'/.exec(readFileSync(schemaPath, 'utf8'));
  if (!m || !lock || m[1] !== lock.sha256) fail('vendored schema does not match protocol.lock.json');
  console.log(`gen:protocol: source not present; vendored schema matches lock ${lock.sha256.slice(0, 12)}`);
  process.exit(0);
} else {
  fail(`source not found: ${sourcePath} (set PROTOCOL_SOURCE)`);
}

const sha256 = createHash('sha256').update(raw).digest('hex');
const schema = JSON.parse(raw);
const defs = schema.$defs ?? {};

const ident = (s) => s.replace(/[^A-Za-z0-9_]/g, '_');
const refName = (ref) => ref.replace('#/$defs/', '');
const doc = (text, indent) =>
  text ? `${indent}/** ${String(text).replace(/\*\//g, '*\\/').replace(/\n/g, `\n${indent} * `)} */\n` : '';

function tsType(s) {
  if (s.$ref) return ident(refName(s.$ref));
  if (s.enum) return s.enum.map((v) => JSON.stringify(v)).join(' | ');
  const types = Array.isArray(s.type) ? s.type : [s.type];
  return types
    .map((t) => {
      switch (t) {
        case 'string':
          return 'string';
        case 'integer':
        case 'number':
          return 'number';
        case 'boolean':
          return 'boolean';
        case 'null':
          return 'null';
        case 'array':
          return `Array<${tsType(s.items ?? {})}>`;
        case 'object':
          if (s.properties) return inlineObject(s, '  ');
          if (s.additionalProperties && typeof s.additionalProperties === 'object')
            return `Record<string, ${tsType(s.additionalProperties)}>`;
          return 'Record<string, unknown>';
        default:
          return 'unknown';
      }
    })
    .join(' | ');
}

function inlineObject(s, indent) {
  const req = new Set(s.required ?? []);
  const lines = Object.keys(s.properties)
    .sort()
    .map(
      (k) =>
        `${doc(s.properties[k].description, indent + '  ')}${indent}  ${k}${req.has(k) ? '' : '?'}: ${tsType(s.properties[k])};`,
    );
  return `{\n${lines.join('\n')}\n${indent}}`;
}

let out = `// GENERATED by \`pnpm gen:protocol\` from getproperty-api contract/device-protocol.json — do not edit.\n`;
out += `// ${schema.title} · x-api-version ${schema['x-api-version']} · sha256 ${sha256}\n\n`;
for (const name of Object.keys(defs).sort()) {
  const d = defs[name];
  const n = ident(name);
  out += doc(d.description, '');
  if (d.enum) {
    out += `export type ${n} = ${d.enum.map((v) => JSON.stringify(v)).join(' | ')};\n`;
    out += `export const ${n}Values = ${JSON.stringify(d.enum)} as const;\n\n`;
  } else if (d.type === 'object' && d.properties) {
    out += `export interface ${n} ${inlineObject(d, '')}\n\n`;
  } else {
    out += `export type ${n} = ${tsType(d)};\n\n`;
  }
}
out += `/** Topic suffixes declared in x-topics, keyed by suffix after \`gp/v1/<gatewayId>/\`. */\n`;
const topics = schema['x-topics'] ?? {};
const suffixes = Object.keys(topics)
  .map((t) => t.replace('gp/v1/<gatewayId>/', ''))
  .sort();
out += `export type TopicSuffix = ${suffixes.map((s) => JSON.stringify(s)).join(' | ')};\n`;
out += `export const TOPICS = ${JSON.stringify(
  Object.fromEntries(
    suffixes.map((s) => {
      const t = topics[`gp/v1/<gatewayId>/${s}`];
      return [s, { direction: t.direction, payload: t.payload, qos: t.qos, retained: t.retained }];
    }),
  ),
  null,
  2,
)} as const;\n`;
out += `export const LWT_PAYLOAD = ${JSON.stringify(schema['x-lwt']?.payload ?? {})} as const;\n`;
// Protocol 1.2 (D-235, D-244): revision, broker login and the exact gateway ACL. Older contracts carry none of these;
// the agent then falls back to the topic directions above (publish = `out`, subscribe = `in`).
const prefix = 'gp/v1/<gatewayId>/';
const stripTopic = (t) => {
  if (!t.startsWith(prefix)) fail(`x-acl topic ${t} is outside ${prefix}`);
  const s = t.slice(prefix.length);
  if (!suffixes.includes(s)) fail(`x-acl topic ${t} is not declared in x-topics`);
  return s;
};
const acl = schema['x-acl'];
const byDirection = (dir) => suffixes.filter((s) => topics[`${prefix}${s}`].direction === dir);
out += `/** \`x-protocol-version\` of the contract (absent before 1.2). */\n`;
out += `export const PROTOCOL_VERSION = ${JSON.stringify(schema['x-protocol-version'] ?? '1.0')};\n`;
out += `/** \`x-acl\`: the only topics a gateway may publish / subscribe to (suffixes), max QoS, retain on publish. */\n`;
out += `export const MQTT_ACL = ${JSON.stringify(
  {
    publish: acl ? acl.publish.map(stripTopic) : byDirection('out'),
    subscribe: acl ? acl.subscribe.map(stripTopic) : byDirection('in'),
    maxQos: acl?.maxQos ?? 1,
    retainOnPublish: acl?.retainOnPublish ?? false,
  },
  null,
  2,
)} as const satisfies { publish: readonly TopicSuffix[]; subscribe: readonly TopicSuffix[]; maxQos: number; retainOnPublish: boolean };\n`;
const auth = schema['x-mqtt-auth'];
out += `/** \`x-mqtt-auth\`: broker login (client id / username template; transports). */\n`;
out += `export const MQTT_AUTH = ${JSON.stringify(
  {
    clientId: auth?.clientId ?? 'gw-<gatewayId>',
    passwordRequired: !!auth?.password,
    transports: Object.keys(auth?.transports ?? { mtls: {} }).sort(),
  },
  null,
  2,
)} as const;\n`;

const schemaOut =
  `// GENERATED by \`pnpm gen:protocol\` — vendored copy of getproperty-api contract/device-protocol.json. Do not edit.\n` +
  `export const PROTOCOL_SHA256 = '${sha256}';\n` +
  `export const PROTOCOL_API_VERSION = '${schema['x-api-version']}';\n` +
  `export const protocolSchema = ${JSON.stringify(schema, null, 2)} as const;\n`;

const lockOut =
  JSON.stringify(
    {
      source: 'getproperty-api/contract/device-protocol.json',
      sha256,
      apiVersion: schema['x-api-version'],
    },
    null,
    2,
  ) + '\n';

if (check) {
  if (!lock) fail('protocol.lock.json missing — run pnpm gen:protocol');
  if (lock.sha256 !== sha256)
    fail(`contract changed (${lock.sha256.slice(0, 12)} → ${sha256.slice(0, 12)}); run pnpm gen:protocol and review`);
  const stale = [
    [typesPath, out],
    [schemaPath, schemaOut],
  ].filter(([p, c]) => !existsSync(p) || readFileSync(p, 'utf8') !== c);
  if (stale.length) fail(`stale generated files: ${stale.map(([p]) => relative(root, p)).join(', ')}`);
  console.log(`gen:protocol: up to date (${sha256.slice(0, 12)})`);
} else {
  writeFileSync(typesPath, out);
  writeFileSync(schemaPath, schemaOut);
  writeFileSync(lockPath, lockOut);
  console.log(`gen:protocol: wrote types/schema, pinned ${sha256.slice(0, 12)} from ${relative(root, sourcePath)}`);
}
